from pysat.solvers import Glucose3
from pysat.card import CardEnc

n = 24
weeks = 4
groups_per_week = 6
group_size = 4

def var_id(w, p, g):
    return w * n * groups_per_week + p * groups_per_week + g + 1

solver = Glucose3()

# Each golfer in each week is in exactly one group
for w in range(weeks):
    for p in range(n):
        clause = [var_id(w, p, g) for g in range(groups_per_week)]
        solver.add_clause(clause)
        for g1 in range(groups_per_week):
            for g2 in range(g1 + 1, groups_per_week):
                solver.add_clause([-var_id(w, p, g1), -var_id(w, p, g2)])

# Each group in each week has exactly 4 golfers
for w in range(weeks):
    for g in range(groups_per_week):
        # At most 4
        cnf = CardEnc.atmost(lits=[var_id(w, p, g) for p in range(n)], bound=4)
        for clause in cnf.clauses:
            solver.add_clause(clause)
        # At least 4
        cnf = CardEnc.atleast(lits=[var_id(w, p, g) for p in range(n)], bound=4)
        for clause in cnf.clauses:
            solver.add_clause(clause)

# Create meet variables
meet_start = n * weeks * groups_per_week + 1
meet = {}
idx = 0
for p1 in range(n):
    for p2 in range(p1 + 1, n):
        for w in range(weeks):
            meet[(p1, p2, w)] = meet_start + idx
            idx += 1

print(f"Total variables: {meet_start + idx - 1}")

# Add constraints for meet variables
for p1 in range(n):
    for p2 in range(p1 + 1, n):
        for w in range(weeks):
            for g in range(groups_per_week):
                solver.add_clause([
                    -var_id(w, p1, g),
                    -var_id(w, p2, g),
                    meet[(p1, p2, w)]
                ])

# For each pair, at most 1 week where they meet
for p1 in range(n):
    for p2 in range(p1 + 1, n):
        cnf = CardEnc.atmost(lits=[meet[(p1, p2, w)] for w in range(weeks)], bound=1)
        for clause in cnf.clauses:
            solver.add_clause(clause)

print("Solving...")
result = solver.solve()
print(f"Result: {result}")

if result:
    model = solver.get_model()
    solution = [0] * (n * weeks)
    for w in range(weeks):
        for p in range(n):
            for g in range(groups_per_week):
                if model[var_id(w, p, g) - 1] > 0:
                    solution[w * n + p] = g
                    break
    print("Solution found!")
    print(solution)

    # Verify
    def check_solution(sol):
        for w in range(weeks):
            groups = {}
            for p in range(n):
                g = sol[w * n + p]
                if g not in groups:
                    groups[g] = []
                groups[g].append(p)
            if len(groups) != groups_per_week:
                return False
            for g, members in groups.items():
                if len(members) != group_size:
                    return False
        pair_weeks = {}
        for w in range(weeks):
            for p1 in range(n):
                for p2 in range(p1 + 1, n):
                    if sol[w * n + p1] == sol[w * n + p2]:
                        pair = (p1, p2)
                        if pair in pair_weeks:
                            return False
                        pair_weeks[pair] = w
        return True

    print(f"Valid: {check_solution(solution)}")
else:
    print("No solution")
